package org.rabochaya.maptests;
import java.io.*;
/** Independent static GIF writer: explicit LSB CLEAR/index pairs keep code size fixed. */
public final class GifFixtures {
 private GifFixtures(){}
 static void u16(ByteArrayOutputStream out,int n){out.write(n&255);out.write(n>>>8&255);}
 static void palette(ByteArrayOutputStream out){for(int color:new int[]{0,0x5080b0,0x463c64,0x349464,0x66bc64,0xb81464,0x786464,0xff0000,0x00ff00,0x0000ff,0xffffff,0x102030,0x304050,0x506070,0x708090,0x90a0b0}){out.write(color>>>16&255);out.write(color>>>8&255);out.write(color&255);}}
 static int index(int x,int y,int width,int height){if(x==0&&y==0)return 0;if(x==1&&y==1)return 2;if(x==16&&y==16)return 3;if(x==17&&y==17)return 4;if(x==width-1&&y==height-1)return 5;if(x==2&&y==2)return 6;return 1;}
 public static byte[] image(int width,int height,boolean local,boolean interlaced,boolean version89){ByteArrayOutputStream out=new ByteArrayOutputStream();try{out.write((version89?"GIF89a":"GIF87a").getBytes("US-ASCII"));}catch(IOException e){throw new AssertionError(e);}u16(out,width);u16(out,height);out.write(local?0:0xf3);out.write(0);out.write(0);if(!local)palette(out);if(version89){out.write(0x21);out.write(0xf9);out.write(4);out.write(1);u16(out,0);out.write(0);out.write(0);}out.write(0x2c);u16(out,0);u16(out,0);u16(out,width);u16(out,height);out.write((local?0x83:0)|(interlaced?0x40:0));if(local)palette(out);out.write(4);ByteArrayOutputStream data=new ByteArrayOutputStream();int accumulator=0,bits=0;int[] starts=interlaced?new int[]{0,4,2,1}:new int[]{0},steps=interlaced?new int[]{8,8,4,2}:new int[]{1};for(int pass=0;pass<starts.length;pass++)for(int y=starts[pass];y<height;y+=steps[pass])for(int x=0;x<width;x++)for(int code:new int[]{16,index(x,y,width,height)}){accumulator|=code<<bits;bits+=5;while(bits>=8){data.write(accumulator&255);accumulator>>>=8;bits-=8;}}accumulator|=17<<bits;bits+=5;while(bits>=8){data.write(accumulator&255);accumulator>>>=8;bits-=8;}if(bits>0)data.write(accumulator&255);byte[] packed=data.toByteArray();for(int at=0;at<packed.length;at+=255){int count=Math.min(255,packed.length-at);out.write(count);out.write(packed,at,count);}out.write(0);out.write(0x3b);return out.toByteArray();}
 public static byte[] field(byte[] source,int at,int value){byte[] bytes=source.clone();bytes[at]=(byte)value;return bytes;}
 /** Small explicit-code controls; caller keeps the dictionary below the first width transition. */
 public static byte[] fixedCodes(int width,int height,int minimum,int...codes){byte[] source=image(width,height,false,false,true);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(source,0,79);out.write(minimum);ByteArrayOutputStream data=new ByteArrayOutputStream();int widthBits=minimum+1,accumulator=0,bits=0;for(int code:codes){if(code<0||code>=(1<<widthBits))throw new IllegalArgumentException();accumulator|=code<<bits;bits+=widthBits;while(bits>=8){data.write(accumulator&255);accumulator>>>=8;bits-=8;}}if(bits>0)data.write(accumulator&255);byte[] packed=data.toByteArray();for(int at=0;at<packed.length;at+=255){int count=Math.min(255,packed.length-at);out.write(count);out.write(packed,at,count);}out.write(0);out.write(0x3b);return out.toByteArray();}
 static final class Codes {final ByteArrayOutputStream data=new ByteArrayOutputStream();int accumulator,bits;void add(int value,int width){accumulator|=value<<bits;bits+=width;while(bits>=8){data.write(accumulator&255);accumulator>>>=8;bits-=8;}}byte[] done(){if(bits>0)data.write(accumulator&255);return data.toByteArray();}}
 /** Literal stream exercises all code widths and full dictionary with/without CLEAR. */
 public static byte[] literalStream(int width,int height,boolean clearOnFull){byte[] source=image(width,height,false,false,true);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(source,0,79);out.write(4);Codes codes=new Codes();int bits=5,next=18;boolean previous=false;codes.add(16,bits);for(int y=0;y<height;y++)for(int x=0;x<width;x++){codes.add((x+y*3)%16,bits);if(previous&&next<4096){next++;if(next==(1<<bits)&&bits<12)bits++;}previous=true;if(clearOnFull&&next==4096){codes.add(16,bits);bits=5;next=18;previous=false;}}codes.add(17,bits);byte[] packed=codes.done();for(int at=0;at<packed.length;at+=255){int count=Math.min(255,packed.length-at);out.write(count);out.write(packed,at,count);}out.write(0);out.write(0x3b);return out.toByteArray();}
}
